	CONSTRAINT "media_submissions_consent_check" CHECK (NOT "media_submissions"."instagram_display_consent" OR "media_submissions"."instagram_handle" IS NOT NULL),
	CONSTRAINT "media_submissions_updated_by_check" CHECK (length("media_submissions"."updated_by") BETWEEN 1 AND 256)
);
